export const cycleSource='https://openstax.org/books/anatomy-and-physiology-2e/pages/19-3-cardiac-cycle';
export const breathSource='https://openstax.org/books/anatomy-and-physiology-2e/pages/22-3-the-process-of-breathing';
const clean=n=>n.toLowerCase().replace(/\.[lr]\.\d+$|\.\d+$/g,'');
export function heartPart(r){const n=clean(r.name);if(r.layer==='nervous')return null;if(n==='right atrium'||n==='cardiac atrium'&&/\.r\./.test(r.name))return'ra';if(n==='left atrium'||n==='cardiac atrium'&&/\.l\./.test(r.name))return'la';if(/^(heart )?right ventricle$/.test(n))return'rv';if(/^(heart )?left ventricle$/.test(n))return'lv';if(/right atrioventricular valve|^tricuspid valve$/.test(n))return'tricuspid';if(/left atrioventricular valve|^mitral valve$/.test(n))return'mitral';if(/pulmonary valve/.test(n))return'pulmonary';if(/^(left coronary|right coronary|non-coronary) leaflet$|^aortic valve$/.test(n))return'aortic';if(/papillary|chordae|interventricular septum/.test(n))return'inside';if(r.layer==='cardiovascular'&&(r.name==='Marginal artery.l.001'||/coronary.*arter|coronary sinus|cardiac vein|coronary vein|coronary artery/.test(n)||['circumflex artery of heart','anterior interventricular artery','septal branches of anterior interventricular artery'].includes(n)))return'coronary';if(n==='pulmonary trunk')return'pt';if(/pulmonary vein/.test(n))return'pv';if(/vena cava/.test(n)&&!/abdominal/.test(n))return'vc';if(/^(ascending aorta|aortic arch|arch of aorta)$/.test(n))return'ao';if(n==='diaphragm')return'diaphragm';if(r.layer==='visceral'&&/lung|bronchopulmonary segment/.test(n)&&!/bronchus|hilus|ligament/.test(n))return'lung';return null;}
